export function n_add(x, y) { return x + y; }
export function n_multiply(x, y) { const r = x * y; return [r, 1 / r]; }
export function n_bits(x) { return [x | 0, x >>> 0, ~x, x << 1]; }
export function n_compare(x, y) { return [x < y, x <= y, x === y, x == y]; }
export function n_index(x) { return ["zero", "one", "two"][x]; }
export function n_increment(x) { x++; return x; }
export function n_negate(x) { return [-x, +x, 1 / -x]; }
export function n_fixed(x) { return x.toFixed(1); }
export function n_math(x) { return [Math.floor(x), Math.abs(x), Math.max(x, 1)]; }
export function n_loop(x) { let n = 0; for (let i = 0; i < x && i < 50; i++) n += i; return n; }
export function n_literal(x) { return x === 1 ? "one" : x === 2 ? "two" : "other"; }
export function b_not(x) { return [!x, x === true, x === false, x ? 1 : 2, x & 1]; }
export function b_true(x) { return x === true ? "true" : "not true"; }
export function big_add(x) { return x + 1n; }
export function sym_text(x) { return x.description; }
export function nil_only(x, y) { return [x === null, y === undefined, x ?? "was nil", y ?? "was nil"]; }
